mapper.select:
SELECT PAYHSRCSECINFO.SECID, PAYHSRCSECINFO.SECNAME, PAYHSRCSECINFO.SECFULLNAME, PAYHSRCSECINFO.SECCODE, PAYHSRCSECINFO.MARKET, PAYHSRCSECINFO.INSTITUTION, PAYHSRCSECINFO.ISSUEPRICE, to_char(PAYHSRCSECINFO.PUBENDDATE,'yyyy-MM-dd') PUBENDDATE, to_char(PAYHSRCSECINFO.VDATE,'yyyy-MM-dd') VDATE, to_char(PAYHSRCSECINFO.MDATE,'yyyy-MM-dd') MDATE, PAYHSRCSECINFO.ISSUEAMT/100000000 ISSUEAMT, CUSTOMER_INFO1.CUSTOMER_NAME issuerName, PAYHSRCSECINFO.SECTYPE, PAYHSRCSECINFO.SECTYPE2, CASE PAYHSRCSECINFO.ISSUETYPE WHEN '01' THEN '1' ELSE '2' END AS ISSUETYPE, PAYHSRCSECINFO.BLNAREA, PAYHSRCSECINFO.ISSUS, PAYHSRCSECINFO.ISSECBOND, PAYHSRCSECINFO.CITY_INVEST_SEC_CHB CITYINVESTSECWIND, PAYHSRCSECINFO.CCY, PAYHSRCSECINFO.FACEVALUE, PAYHSRCSECINFO.GUARANTOR, PAYHSRCSECINFO.GUARTYPE, CASE WHEN ( PAYHSRCSECINFO.CALLOPTION = 'Y' OR PAYHSRCSECINFO.PUTOPTION = 'Y' ) THEN 'Y' ELSE 'N' END AS IS_RIGHT, PAYHSRCSECINFO.REMARK, PAYHSRCSECINFO.COUPONSPECIES, PAYHSRCSECINFO.INTERESTRATE, PAYHSRCSECINFO.PAPERIR, PAYHSRCSECINFO.SPREADRATE_8 SPREADRATE8, PAYHSRCSECINFO.RATECODE, PAYHSRCSECINFO.COEFFICIENT, PAYHSRCSECINFO.TOPRATE, PAYHSRCSECINFO.BOTTOMRATE, PAYHSRCSECINFO.RESETTYPE, PAYHSRCSECINFO.OBSERVEBEFDAY, PAYHSRCSECINFO.OBSERVEBEFUNIT, CASE WHEN ( PAYHSRCSECINFO.RATEBASIC = 'A/A_B_COUP' OR PAYHSRCSECINFO.PUTOPTION = 'A_B_DAY' ) THEN 'A/A' ELSE PAYHSRCSECINFO.RATEBASIC END AS RATEBASIC, CASE WHEN PAYHSRCSECINFO.RATEBASIC = 'A/A_B_COUP' THEN '02' WHEN PAYHSRCSECINFO.RATEBASIC = 'A/A_B_DAY' THEN '01' END AS BASISSTYLE, PAYHSRCSECINFO.WORKDAYRULE, PAYHSRCSECINFO.PAYCYCLE, PAYHSRCSECINFO.SCHECALRULE, PAYHSRCSECINFO.FIRSTRATEDAY, PAYHSRCSECOPTION.OPTIONTYPE, PAYHSRCSECOPTION.THEORYOPTIONPAYDAY,
PAYHSRCSECRATING.RATING ztGradeResult, PAYHSRCSECRATING.RATINGORG ztGradeOrgId, PAYHSRCSECRATING2.RATING zxGradeResult, PAYHSRCSECRATING2.RATINGORG zxGradeOrgId, PAYHSRCSECINFO.IS_GREEN_BOND, to_char(PAYHSRCSECINFO.DELISTING_DATE,'yyyy-MM-dd') DELISTINGDATE, PAYHSRCSECINFO.CROSS_MARKET_CODE, PAYHSRCSECINFO.FIRST_RATE_DETERMINATION_DATE firstConfirmDate FROM INTERF_PAYHSRCSECINFO PAYHSRCSECINFO LEFT JOIN INTERF_CUSTOMER_INFO CUSTOMER_INFO1 ON PAYHSRCSECINFO.ISSUERSHORT = CUSTOMER_INFO1.CUSTOMER_ID LEFT JOIN INTERF_CUSTOMER_INFO CUSTOMER_INFO2 ON CUSTOMER_INFO1.CUSTOMER_ID = PAYHSRCSECINFO.GUARANTOR LEFT JOIN ( SELECT SECID, OPTIONTYPE, THEORYOPTIONPAYDAY FROM ( SELECT ROW_NUMBER ( ) OVER ( PARTITION BY PAYHSRCSECOPTION.SECID ORDER BY PAYHSRCSECOPTION.THEORYOPTIONPAYDAY DESC ) NUM, SECID, OPTIONTYPE, THEORYOPTIONPAYDAY FROM INTERF_PAYHSRCSECOPTION PAYHSRCSECOPTION WHERE PAYHSRCSECOPTION.THEORYOPTIONPAYDAY > to_date( #{platformDate}, 'YYYY-MM-DD' ) ) WHERE NUM = 1 ) PAYHSRCSECOPTION ON PAYHSRCSECOPTION.SECID = PAYHSRCSECINFO.SECID ---接口债券评级信息表 LEFT JOIN (SELECT SECID,RATING,RATINGORG,row_number () over (partition BY SECID ORDER BY RATING ASC) num FROM INTERF_PAYHSRCSECRATING WHERE ratingtype='C') PAYHSRCSECRATING ON PAYHSRCSECRATING.SECID = PAYHSRCSECINFO.SECID AND PAYHSRCSECRATING.NUM = 1 LEFT JOIN (SELECT SECID,RATING,RATINGORG,row_number () over (partition BY SECID ORDER BY RATING ASC) num FROM INTERF_PAYHSRCSECRATING WHERE ratingtype='I') PAYHSRCSECRATING2 ON PAYHSRCSECRATING2.SECID = PAYHSRCSECINFO.SECID AND PAYHSRCSECRATING2.NUM = 1 left join SYS_DATADICT_LIST sdl_tp on PAYHSRCSECINFO.MARKET = sdl_tp.ITEM_CODE and sdl_tp.DICT_CODE='TRADE_PLACE' left join SYS_DATADICT_LIST sdl_ro on PAYHSRCSECINFO.ISSUEPRICE = sdl_ro.ITEM_CODE and sdl_ro.DICT_CODE='REGIST_ORG' left join SYS_DATADICT_LIST sdl_catt on PAYHSRCSECINFO.SECTYPE = sdl_catt.ITEM_CODE and sdl_catt.DICT_CODE='WINDTYPEONE' left join SYS_DATADICT_LIST sdl_catth on PAYHSRCSECINFO.SECTYPE2 = sdl_catth.ITEM_CODE and sdl_catth.DICT_CODE='WINDTYPETWO' left join SYS_DATADICT_LIST sdl_cs on PAYHSRCSECINFO.COUPONSPECIES = sdl_cs.ITEM_CODE and sdl_cs.DICT_CODE='COUPON_SPECIES' left join SYS_DATADICT_LIST sdl_it on PAYHSRCSECINFO.INTERESTRATE = sdl_it.ITEM_CODE and sdl_it.DICT_CODE='INT_TYPE' left join SYS_DATADICT_LIST sdl_fu on PAYHSRCSECINFO.payCycle = sdl_fu.ITEM_CODE and sdl_fu.DICT_CODE='FREQUENCY_UNIT' left join SYS_DATADICT_LIST sdl_sd on PAYHSRCSECINFO.RATECODE = sdl_sd.ITEM_CODE and sdl_sd.DICT_CODE='SECRATE_DATA' left join SYS_DATADICT_LIST sdl_em on PAYHSRCSECOPTION.OPTIONTYPE = sdl_em.ITEM_CODE and sdl_em.DICT_CODE='EXEC_MODE' left join SYS_DATADICT_LIST sdl_is on PAYHSRCSECINFO.ISSUS = sdl_is.ITEM_CODE and sdl_is.DICT_CODE='YES_OR_NO' left join SYS_DATADICT_LIST sdl_isb on PAYHSRCSECINFO.ISSECBOND=sdl_isb.ITEM_CODE and sdl_isb.DICT_CODE='YES_OR_NO' left join SYS_DATADICT_LIST sdl_yo on PAYHSRCSECINFO.CITY_INVEST_SEC_CHB = sdl_yo.ITEM_CODE and sdl_yo.DICT_CODE='YES_OR_NO' left join SYS_DATADICT_LIST sdl_ccy on PAYHSRCSECINFO.ccy=sdl_ccy.ITEM_CODE and sdl_ccy.DICT_CODE='CCY' left join SYS_DATADICT_LIST sdl_rt on PAYHSRCSECINFO.ISSUETYPE = sdl_rt.ITEM_CODE and sdl_rt.DICT_CODE='RAISE_TYPE' left join SYS_DATADICT_LIST sdl_ba on PAYHSRCSECINFO.BLNAREA = sdl_ba.ITEM_CODE and sdl_ba.DICT_CODE='BLN_AREA' left join SYS_DATADICT_LIST sdl_sgt on PAYHSRCSECINFO.GUARTYPE = sdl_sgt.ITEM_CODE and sdl_sgt.DICT_CODE='SVR_GUA_TYPE' -- left join SYS_DATADICT_LIST sdl_tc on PAYHSRCSECINFO.CALENDARID = sdl_tc.ITEM_CODE and sdl_tc.DICT_CODE='TRANSACTION_CALENDAR'
PAYHSRCSECINFO.VDATE <= to_date ( #{platformDate}, 'YYYY-MM-DD' )
AND PAYHSRCSECINFO.SECID = #{secId,jdbcType=VARCHAR}
AND PAYHSRCSECINFO.MARKET = #{market,jdbcType=VARCHAR}
AND PAYHSRCSECINFO.SECTYPE in
#{item}
AND PAYHSRCSECINFO.SECTYPE2 in
#{item}
AND PAYHSRCSECINFO.institution = #{institution,jdbcType=VARCHAR}
AND PAYHSRCSECINFO.ISSUERSHORT = #{issuer,jdbcType=VARCHAR}
AND PAYHSRCSECINFO.PUBENDDATE >= #{issueDateStart,jdbcType=DATE}
AND PAYHSRCSECINFO.PUBENDDATE <= #{issueDateEnd,jdbcType=DATE}
AND PAYHSRCSECINFO.VDATE >= #{vdateStart,jdbcType=DATE}
AND PAYHSRCSECINFO.VDATE <= #{vdateEnd,jdbcType=DATE}
AND PAYHSRCSECINFO.MDATE >= #{mdateStart,jdbcType=DATE}
AND PAYHSRCSECINFO.MDATE <= #{mdateEnd,jdbcType=DATE}
AND PAYHSRCSECOPTION.THEORYOPTIONPAYDAY >= #{theOryOptionPayDayStart,jdbcType=DATE}
AND PAYHSRCSECOPTION.THEORYOPTIONPAYDAY <= #{theOryOptionPayDayEnd,jdbcType=DATE}
AND PAYHSRCSECINFO.COUPONSPECIES = #{couponSpecies,jdbcType=VARCHAR}
AND PAYHSRCSECINFO.INTERESTRATE = #{interestRate,jdbcType=VARCHAR}
AND PAYHSRCSECINFO.PAYCYCLE = #{payCycle,jdbcType=VARCHAR}
AND PAYHSRCSECINFO.CCY = #{ccy,jdbcType=VARCHAR}
AND PAYHSRCSECINFO.ISSUS = #{isSus,jdbcType=VARCHAR}
AND ( PAYHSRCSECINFO.CALLOPTION = 'Y' OR PAYHSRCSECINFO.PUTOPTION = 'Y')
AND ( PAYHSRCSECINFO.CALLOPTION = 'N' AND PAYHSRCSECINFO.PUTOPTION = 'N')
AND PAYHSRCSECOPTION.OPTIONTYPE = #{optionType,jdbcType=VARCHAR}
AND PAYHSRCSECRATING2.RATING in (#{zxGrade,jdbcType=VARCHAR})
AND PAYHSRCSECRATING.RATING in (#{ztGrade,jdbcType=VARCHAR})
AND ( PAYHSRCSECINFO.SECID like '%' || #{search} || '%' OR PAYHSRCSECINFO.SECNAME like '%' || #{search} || '%' OR PAYHSRCSECINFO.SECFULLNAME like '%' || #{search} || '%' OR CUSTOMER_INFO1.CUSTOMER_NAME like '%' || #{search} || '%' OR PAYHSRCSECINFO.SECCODE like '%' || #{search} || '%' OR PAYHSRCSECINFO.MARKET like '%' || #{search} || '%' OR PAYHSRCSECINFO.institution like '%' || #{search} || '%' OR PAYHSRCSECINFO.ISSUERSHORT like '%' || #{search} || '%' OR to_char(PAYHSRCSECINFO.PUBENDDATE,'yyyy-MM-dd') = #{search} OR to_char(PAYHSRCSECINFO.VDATE,'yyyy-MM-dd') = #{search} OR to_char(PAYHSRCSECINFO.MDATE,'yyyy-MM-dd') = #{search} OR to_char(PAYHSRCSECOPTION.THEORYOPTIONPAYDAY,'yyyy-MM-dd') = #{search} OR PAYHSRCSECINFO.COUPONSPECIES like '%' || #{search} || '%' OR PAYHSRCSECINFO.INTERESTRATE like '%' || #{search} || '%' OR PAYHSRCSECINFO.PAYCYCLE like '%' || #{search} || '%' OR PAYHSRCSECINFO.CCY like '%' || #{search} || '%' OR PAYHSRCSECINFO.ISSUS like '%' || #{search} || '%' OR PAYHSRCSECOPTION.OPTIONTYPE like '%' || #{search} || '%' OR PAYHSRCSECRATING2.RATING like '%' || #{search} || '%' OR PAYHSRCSECRATING.RATING like '%' || #{search} || '%' OR
sdl_tp.ITEM_VALUE like '%' || #{search} || '%' OR sdl_ro.ITEM_VALUE like '%' || #{search} || '%' OR sdl_catt.ITEM_VALUE like '%' || #{search} || '%' OR sdl_catth.ITEM_VALUE like '%' || #{search} || '%' OR sdl_cs.ITEM_VALUE like '%' || #{search} || '%' OR sdl_it.ITEM_VALUE like '%' || #{search} || '%' OR sdl_fu.ITEM_VALUE like '%' || #{search} || '%' OR sdl_sd.ITEM_VALUE like '%' || #{search} || '%' OR sdl_em.ITEM_VALUE like '%' || #{search} || '%' OR sdl_is.ITEM_VALUE like '%' || #{search} || '%' OR sdl_isb.ITEM_VALUE like '%' || #{search} || '%' OR sdl_yo.ITEM_VALUE like '%' || #{search} || '%' OR sdl_ccy.ITEM_VALUE like '%' || #{search} || '%' OR sdl_rt.ITEM_VALUE like '%' || #{search} || '%' OR sdl_ba.ITEM_VALUE like '%' || #{search} || '%' OR sdl_sgt.ITEM_VALUE like '%' || #{search} || '%'
)
ORDER BY PAYHSRCSECINFO.SECTYPE, PAYHSRCSECINFO.SECTYPE2, PAYHSRCSECINFO.VDATE, PAYHSRCSECINFO.SECID

select SECID, SCHEDUTYPE, TOTALINTERESTSTARTDAY, TOTALINTERESTENDDAY, INTERESTSTARTDAY, INTERESTENDDAY, INTERESTPAYDAY, COUPONRATE, ACCRUEINTAMT, DAILYACCRUEINT, PRINAMTPAY, CASHPAY, PRINAMT, SOURCE from INTERF_PAYHSRCSECSCHEDULE where SECID = #{secId,jdbcType=VARCHAR}
AND INTERESTSTARTDAY >= #{maxTradeDate,jdbcType=VARCHAR}
and SCHEDUTYPE in (
#{item}
)
ORDER BY INTERESTPAYDAY ASC
